/**
 * Board and stone materials.
 *
 * The images are generated by `scripts/make-assets.mjs` into src/web/assets
 * and copied to frontend/dist/assets by sync-dist. They are loaded by
 * relative URL (the page CSP is `img-src 'self' data:`), lazily, once.
 *
 *   const m = await loadMaterials();
 *   ctx.drawImage(m.surfaces.kaya, 0, 0, w, h);              // board surface
 *   const img = m.white[stoneVariant(x, y, WHITE)];           // stone sprite
 *   ctx.drawImage(img, cx - r, cy - r, 2 * r, 2 * r);        // disc fills the sprite
 *   const theme = THEME_COLORS.kaya;                          // grid colours
 *
 * Surfaces are 2048×2048 and meant to cover the whole board (not tiled).
 * Grain runs vertically. Stone sprites are 256×256 with straight alpha; the
 * disc's diameter equals the sprite width; lighting is from the top-left; no
 * shadow is baked in, so draw a contact shadow first. For crisp downscaling
 * set `ctx.imageSmoothingQuality = "high"`.
 *
 * Nothing here throws: a failed image resolves as null (or is left out of
 * the variant arrays), and callers keep their procedural fallback.
 */

/** v4 ships one texture: the kaya grain behind the "wood" board (at 25 %). */
export const SURFACES = ["kaya"];

/** Older material names map onto the new surfaces. */
export const MATERIAL_ALIASES = { wood: "kaya" };

export const STONE_COUNTS = { black: 4, white: 8 };

/**
 * Colours tuned per surface. All are opaque except `shadow` (a contact shadow
 * colour for the stone's radial gradient). make-assets checks that `line`,
 * `edge` and `star` reach at least 3:1 against the surface's worst 1% of
 * pixels, and `text` at least 3:1 against its mean.
 */
export const THEME_COLORS = {
  kaya: { line: "#3a2611", edge: "#2b1b0a", star: "#2b1b0a", text: "#5e4020", shadow: "rgba(48, 26, 6, 0.38)" },
  katsura: { line: "#47371f", edge: "#342713", star: "#342713", text: "#65502f", shadow: "rgba(58, 42, 18, 0.32)" },
  paper: { line: "#4d4338", edge: "#3a3128", star: "#3a3128", text: "#6d604e", shadow: "rgba(60, 48, 28, 0.26)" },
  slate: { line: "#9fb4a9", edge: "#bccdc3", star: "#c4d4ca", text: "#93a89c", shadow: "rgba(0, 0, 0, 0.5)" },
};
THEME_COLORS.wood = THEME_COLORS.kaya;

let base = "assets/";

/** Where the assets folder lives relative to the page (default "assets/"). */
export function setAssetBase(path) {
  base = path.endsWith("/") ? path : path + "/";
  cache = null;
}

export function assetURL(rel) {
  return base + rel;
}

function loadImage(rel) {
  return new Promise((resolve) => {
    try {
      if (typeof Image === "undefined") return resolve(null);
      const img = new Image();
      img.decoding = "async";
      img.onload = () => {
        if (typeof img.decode === "function") img.decode().then(() => resolve(img), () => resolve(img));
        else resolve(img);
      };
      img.onerror = () => resolve(null);
      img.src = assetURL(rel);
    } catch (_) {
      resolve(null);
    }
  });
}

let cache = null;

/**
 * Load every surface and stone sprite once. Resolves to
 * `{ surfaces: {kaya}, black: [...], white: [...], flatBlack, flatWhite }`;
 * missing images are null (surfaces, flat stones) or omitted (variant arrays).
 */
export function loadMaterials() {
  if (cache) return cache;
  const surfaces = Promise.all(SURFACES.map((name) => loadImage(`surfaces/${name}.webp`)));
  const black = Promise.all(Array.from({ length: STONE_COUNTS.black }, (_, i) => loadImage(`stones/black-${i}.png`)));
  const white = Promise.all(Array.from({ length: STONE_COUNTS.white }, (_, i) => loadImage(`stones/white-${i}.png`)));
  const flat = Promise.all([loadImage("stones/flat-black.png"), loadImage("stones/flat-white.png")]);
  cache = Promise.all([surfaces, black, white, flat])
    .then(([s, b, w, f]) => ({
      surfaces: Object.fromEntries(SURFACES.map((name, i) => [name, s[i]])),
      black: b.filter(Boolean),
      white: w.filter(Boolean),
      flatBlack: f[0],
      flatWhite: f[1],
    }))
    .catch(() => ({ surfaces: { kaya: null }, black: [], white: [], flatBlack: null, flatWhite: null }));
  return cache;
}

/** The surface image for a material name (aliases accepted), or null. */
export function surfaceFor(materials, material) {
  const name = MATERIAL_ALIASES[material] || material;
  return materials?.surfaces?.[name] || null;
}

function hash(x, y, salt) {
  let h = (x * 374761393 + y * 668265263 + salt * 2246822519) ^ 0x27d4eb2f;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h = Math.imul(h ^ (h >>> 16), 2246822519);
  return (h ^ (h >>> 15)) >>> 0;
}

/**
 * A stable variant index for the stone at (x, y): the same point and colour
 * always give the same look. `color` may be 1 / -1 (rules.js BLACK / WHITE)
 * or "black" / "white". Pass `count` if fewer sprites loaded than expected.
 */
export function stoneVariant(x, y, color, count) {
  const white = color === -1 || color === "white" || color === "w" || color === "W";
  const n = Math.max(1, count || (white ? STONE_COUNTS.white : STONE_COUNTS.black));
  return hash(x | 0, y | 0, white ? 2 : 1) % n;
}
